import{_ as t,o,c as a,ag as i}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Usage","description":"","frontmatter":{},"headers":[],"relativePath":"guide/use.md","filePath":"guide/use.md","lastUpdated":1783295281000}'),r={name:"guide/use.md"};function l(n,e,s,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h1><p>EasyYapi supports the following usage methods:</p><h2 id="method-1-export-via-shortcut" tabindex="-1">Method 1: Export via Shortcut <a class="header-anchor" href="#method-1-export-via-shortcut" aria-label="Permalink to &quot;Method 1: Export via Shortcut&quot;">​</a></h2><ol><li>Open a file containing APIs in your project, or select files/folders in the IDEA project panel</li><li>Use shortcut <code>Alt + Shift + E</code> (Windows/Linux) or <code>Ctrl + E</code> (macOS)</li><li>Select the APIs to export</li><li>Choose the export channel: <code>YApi</code> / <code>Markdown</code> / <code>Postman</code></li><li>Click the ✔ button or press Enter to complete the export</li></ol><h2 id="method-2-export-via-right-click" tabindex="-1">Method 2: Export via Right-Click <a class="header-anchor" href="#method-2-export-via-right-click" aria-label="Permalink to &quot;Method 2: Export via Right-Click&quot;">​</a></h2><ol><li>Open a file containing APIs in your project, or select files/folders in the IDEA project panel</li><li>Right-click on the file content or folder</li><li>Select <code>ExportYapi</code> / <code>ExportPostman</code> / <code>ExportMarkdown</code> to export all APIs in the file or folder</li></ol><h2 id="method-3-call-api" tabindex="-1">Method 3: Call API <a class="header-anchor" href="#method-3-call-api" aria-label="Permalink to &quot;Method 3: Call API&quot;">​</a></h2><ol><li>Open a file containing APIs in your project</li><li>Click the gutter icon next to the API method</li><li>Send API requests directly from the IDE</li></ol><p>See <a href="./call">Call API</a> for more details.</p><h2 id="export-only-selected-methods" tabindex="-1">Export Only Selected Methods <a class="header-anchor" href="#export-only-selected-methods" aria-label="Permalink to &quot;Export Only Selected Methods&quot;">​</a></h2><p>Since v3.2.0, EasyYapi respects method-level selection when exporting. Select one or more methods in the editor (either by caret or by selecting a text range that spans them) before triggering an export — only the endpoints whose source method matches (or overrides) the selection are exported, instead of every endpoint in the containing class.</p><p>This works for every export channel (YApi, Postman, Markdown, cURL, HttpClient). If no methods are selected, the whole containing class is exported as before.</p>',12)])])}const m=t(r,[["render",l]]);export{u as __pageData,m as default};
